// Account search (GET /api/v1/search/accounts), backed by core's own Postgres:
// vidra-search does not index accounts at all, so there is no service path to
// be consistent with.
//
// VISIBILITY IS THE WHOLE POINT OF THIS QUERY. The gate is the one
// GetPublicUserProfileByUsername already enforces, reproduced here so the two
// can only ever agree:
//
//	is_active     = TRUE   deactivated, suspended (an admin clearing is_active),
//	                       and hard-deleted accounts all collapse into this one
//	                       flag, and all three are excluded.
//	profile_public = TRUE  the account opted its profile in. Without this, an
//	                       account with no public page would still be
//	                       enumerable by name, which is precisely the leak
//	                       profile_public exists to prevent.
//
// Plus one predicate the profile lookup does NOT have, and must not: NOT
// unlisted. unlisted (§16) is the discovery opt-out — "keep serving my direct
// URLs, keep me out of discovery". A profile fetched BY USERNAME is a direct
// URL, so it ignores the flag; a search result list is discovery, so it honours
// it, exactly as SearchPublicVideos already does for video owners. Applying the
// profile rule alone here would put every unlisted account back into the one
// surface it asked to leave.
//
// Matching is unanchored and case-insensitive over username and display name
// (0002 and 0118 index both for trigrams). The viewer's own mutes and blocks
// are applied the same one-directional way as every other list.
func (q *Queries) SearchPublicAccounts(ctx context.Context, arg SearchPublicAccountsParams) ([]SearchPublicAccountsRow, error) {
	rows, err := q.db.Query(ctx, searchPublicAccounts,
		arg.Query,
		arg.ViewerID,
		arg.ResultOffset,
		arg.ResultLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchPublicAccountsRow
	for rows.Next() {
		var i SearchPublicAccountsRow
		if err := rows.Scan(
			&i.ID,
			&i.Username,
			&i.DisplayName,
			&i.Bio,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateUserProfile = `-- name: UpdateUserProfile :one
UPDATE users
SET display_name = COALESCE($1, display_name),
    bio          = COALESCE($2, bio),
    unlisted     = COALESCE($3, unlisted),
    history_enabled = COALESCE($4, history_enabled),
    profile_public = COALESCE($5, profile_public),
    -- Search & recommendation preferences (search-service W4): the user half of
    -- the two-factor personalization gate. Partial: NULL args leave each unchanged.
    search_history_enabled = COALESCE($6, search_history_enabled),
    personalized_search_enabled = COALESCE($7, personalized_search_enabled),
    personalized_recommendations_enabled = COALESCE($8, personalized_recommendations_enabled),
    -- Per-user opt-in to display the linked Bluesky/ATProto handle on the public
    -- profile (0102). Partial: a NULL arg leaves it unchanged. Default FALSE.
    show_bluesky = COALESCE($9, show_bluesky),
    -- Per-user sensitive-content policy override (0100). Tri-state: unchanged
    -- unless set_sensitive_content_policy is true, in which case a NULL value
    -- clears the override (inherit the instance policy) and a non-NULL enum value
    -- sets it — COALESCE cannot express "set to NULL", so it uses the same CASE
    -- guard AdminUpdateUser uses for the tri-state quota.
    sensitive_content_policy = CASE WHEN $10::bool
                                    THEN $11
                                    ELSE sensitive_content_policy END,
    updated_at   = now()
WHERE id = $12
RETURNING id, username, email, password_hash, role, email_verified, is_active, created_at, updated_at, display_name, bio, storage_quota_bytes, unlisted, bypass_quarantine, deleted_at, pending_email_verification, history_enabled, profile_public, search_history_enabled, personalized_search_enabled, personalized_recommendations_enabled, sensitive_content_policy, show_bluesky
`

type UpdateUserProfileParams struct {
	DisplayName                        *string   `json:"display_name"`
	Bio                                *string   `json:"bio"`
	Unlisted                           *bool     `json:"unlisted"`
	HistoryEnabled                     *bool     `json:"history_enabled"`
	ProfilePublic                      *bool     `json:"profile_public"`
	SearchHistoryEnabled               *bool     `json:"search_history_enabled"`
	PersonalizedSearchEnabled          *bool     `json:"personalized_search_enabled"`
	PersonalizedRecommendationsEnabled *bool     `json:"personalized_recommendations_enabled"`
	ShowBluesky                        *bool     `json:"show_bluesky"`
	SetSensitiveContentPolicy          bool      `json:"set_sensitive_content_policy"`
	SensitiveContentPolicy             *string   `json:"sensitive_content_policy"`
	ID                                 uuid.UUID `json:"id"`
}

func (q *Queries) UpdateUserProfile(ctx context.Context, arg UpdateUserProfileParams) (User, error) {
	row := q.db.QueryRow(ctx, updateUserProfile,
		arg.DisplayName,
		arg.Bio,
		arg.Unlisted,
		arg.HistoryEnabled,
		arg.ProfilePublic,
		arg.SearchHistoryEnabled,
		arg.PersonalizedSearchEnabled,
		arg.PersonalizedRecommendationsEnabled,
		arg.ShowBluesky,
		arg.SetSensitiveContentPolicy,
		arg.SensitiveContentPolicy,
		arg.ID,
	)
	var i User
	err := row.Scan(
		&i.ID,
		&i.Username,
		&i.Email,
		&i.PasswordHash,
		&i.Role,
		&i.EmailVerified,
		&i.IsActive,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DisplayName,
		&i.Bio,
		&i.StorageQuotaBytes,
		&i.Unlisted,
		&i.BypassQuarantine,
		&i.DeletedAt,
		&i.PendingEmailVerification,
		&i.HistoryEnabled,
		&i.ProfilePublic,
		&i.SearchHistoryEnabled,
		&i.PersonalizedSearchEnabled,
		&i.PersonalizedRecommendationsEnabled,
		&i.SensitiveContentPolicy,
		&i.ShowBluesky,
	)
	return i, err
}
